      var am = (a0 + a1) * 0.5;

      // Point on circle in coin local space (x,y,0)
      var lx = Math.cos(am);
      var ly = Math.sin(am);
      // Rotate point by Rx, Ry
      var p = rotatePoint(lx * R, ly * R, 0, rx, ry);
      var pBack = rotatePoint(lx * R, ly * R, -thickness * 0.5, rx, ry);
      var pFront = rotatePoint(lx * R, ly * R, thickness * 0.5, rx, ry);

      var p2l = rotatePoint(Math.cos(a1) * R, Math.sin(a1) * R, -thickness * 0.5, rx, ry);
      var p2f = rotatePoint(Math.cos(a1) * R, Math.sin(a1) * R, thickness * 0.5, rx, ry);

      // Only draw edge segments on the silhouette side roughly
      var viewZ = (pBack.z + pFront.z) * 0.5;
      // Lighting on outward normal (approx rotated radial)
      var n = rotatePoint(lx, ly, 0, rx, ry);
      var ndot = n.x * light.x + n.y * light.y + n.z * light.z;
      var reedDark = (i % 2 === 0) ? 0.72 : 1.05;
      var lit = clamp(0.25 + ndot * 0.75, 0.12, 1.35) * reedDark;

      // Specular kick on edge
      var halfz = (light.z + 1) * 0.5;
      var spec = Math.pow(clamp(ndot, 0, 1), 12) * 0.9;

      var col = metalShade(metal, lit + spec);
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(cx + pBack.x, cy + pBack.y);
      ctx.lineTo(cx + pFront.x, cy + pFront.y);
      ctx.lineTo(cx + p2f.x, cy + p2f.y);
      ctx.lineTo(cx + p2l.x, cy + p2l.y);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  function rotatePoint(x, y, z, rx, ry) {
    // Rx
    var cosx = Math.cos(rx), sinx = Math.sin(rx);
    var y1 = y * cosx - z * sinx;
    var z1 = y * sinx + z * cosx;
    var x1 = x;
    // Ry
    var cosy = Math.cos(ry), siny = Math.sin(ry);
    var x2 = x1 * cosy + z1 * siny;
    var z2 = -x1 * siny + z1 * cosy;
    var y2 = y1;
    return { x: x2, y: y2, z: z2 };
  }

  function metalShade(metal, lit) {
    var c = hexToRgb(metal.base);
    var h = hexToRgb(metal.hi);
    var d = hexToRgb(metal.dark);
    var r, g, b;
    if (lit < 1) {
      var k = lit;
      r = lerp(d.r, c.r, k);
      g = lerp(d.g, c.g, k);
      b = lerp(d.b, c.b, k);
    } else {
      var u = clamp(lit - 1, 0, 1);
      r = lerp(c.r, h.r, u);
      g = lerp(c.g, h.g, u);
      b = lerp(c.b, h.b, u);
    }
    // boost highlights
    if (lit > 1.15) {
      var w = clamp((lit - 1.15) * 2, 0, 1);
      r = lerp(r, 255, w * 0.55);
      g = lerp(g, 255, w * 0.55);
      b = lerp(b, 255, w * 0.45);
    }
    return rgbStr(r, g, b);
  }

  function drawFace(ctx, fx, fy, ellX, ellY, R, metal, isFront, light, t, facing, skew) {
    ctx.save();
    // Clip to ellipse
    ellipsePath(ctx, fx, fy, ellX, ellY);
    ctx.save();
    ctx.clip();

    // Base metallic radial + linear gradient (anisotropy)
    var gx = fx + light.x * ellX * 0.55;
    var gy = fy + light.y * ellY * 0.55;
    var base = ctx.createRadialGradient(gx, gy, R * 0.05, fx, fy, R * 1.05);
    base.addColorStop(0, metal.hi);
    base.addColorStop(0.22, metal.mid);
    base.addColorStop(0.55, metal.base);
    base.addColorStop(0.82, metal.dark);
    base.addColorStop(1, shade(metal.dark, 0.7));
    ctx.fillStyle = base;
    ctx.fillRect(fx - R * 1.2, fy - R * 1.2, R * 2.4, R * 2.4);

    // Linear rake
    var ang = Math.atan2(light.y, light.x);
    ctx.save();
    ctx.translate(fx, fy);
    ctx.rotate(ang);
    var lg = ctx.createLinearGradient(-ellX, 0, ellX, 0);
    lg.addColorStop(0, 'rgba(0,0,0,0.35)');
    lg.addColorStop(0.35, 'rgba(255,255,255,0.05)');
    lg.addColorStop(0.5, 'rgba(255,255,255,0.22)');
    lg.addColorStop(0.65, 'rgba(255,255,255,0.05)');
    lg.addColorStop(1, 'rgba(0,0,0,0.4)');
    ctx.fillStyle = lg;
    ctx.fillRect(-R * 1.2, -R * 1.2, R * 2.4, R * 2.4);
    ctx.restore();

    // Inner rim ring
    ctx.beginPath();
    ctx.ellipse(fx, fy, ellX * 0.92, ellY * 0.92, 0, 0, Math.PI * 2);
    ctx.strokeStyle = metal.rim;
    ctx.lineWidth = Math.max(1.5, R * 0.03);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(fx, fy, ellX * 0.86, ellY * 0.86, 0, 0, Math.PI * 2);
    ctx.strokeStyle = shade(metal.hi, 0.9);
    ctx.lineWidth = Math.max(1, R * 0.012);
    ctx.globalAlpha = 0.55;
    ctx.stroke();
    ctx.globalAlpha = 1;

    // Embossed content — scale with ellipse
    ctx.save();
    ctx.translate(fx, fy);
    ctx.scale(ellX / R, ellY / R);
    // Flip horizontally when showing back via negative facing path
    if (!isFront) {
      ctx.scale(-1, 1);
    }

    if (isFront) {
      drawFrontEmblem(ctx, R, metal, light);
    } else {
      drawBackDenomination(ctx, R, metal, light);
    }
    ctx.restore();

    ctx.restore(); // clip

    // Outer edge stroke
    ellipsePath(ctx, fx, fy, ellX, ellY);
    ctx.strokeStyle = metal.edge;
    ctx.lineWidth = Math.max(1.5, R * 0.025);
    ctx.stroke();

    ctx.restore();
  }

  function drawFrontEmblem(ctx, R, metal, light) {
    // Raised relief emblem: laurel + flame/token void
    var ink = metal.ink;
    var frost = metal.frost;

    // Center medallion
    ctx.beginPath();
    ctx.arc(0, 0, R * 0.32, 0, Math.PI * 2);
    var g = ctx.createRadialGradient(-R * 0.08, -R * 0.1, R * 0.02, 0, 0, R * 0.32);
    g.addColorStop(0, frost);
    g.addColorStop(0.4, metal.mid);
    g.addColorStop(1, metal.dark);
    ctx.fillStyle = g;
    ctx.fill();
    ctx.lineWidth = R * 0.018;
    ctx.strokeStyle = mixHex(metal.dark, metal.hi, 0.3);
    ctx.stroke();

    // Voided token (hexagon)
    ctx.beginPath();
    for (var i = 0; i < 6; i++) {
      var a = -Math.PI / 2 + i * Math.PI / 3;
      var px = Math.cos(a) * R * 0.14;
      var py = Math.sin(a) * R * 0.14;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = metal.dark;
    ctx.fill();
    ctx.strokeStyle = frost;
    ctx.lineWidth = R * 0.012;
    ctx.stroke();

    // Inner flame / W mark
    ctx.beginPath();
    ctx.moveTo(0, -R * 0.09);
    ctx.bezierCurveTo(R * 0.06, -R * 0.02, R * 0.04, R * 0.04, 0, R * 0.1);
    ctx.bezierCurveTo(-R * 0.04, R * 0.04, -R * 0.06, -R * 0.02, 0, -R * 0.09);
    ctx.fillStyle = metal.hi;
    ctx.globalAlpha = 0.85;
    ctx.fill();
    ctx.globalAlpha = 1;

    // W monogram
    ctx.font = 'bold ' + (R * 0.11) + 'px Times New Roman, Georgia, serif';
    ctx.fillStyle = frost;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.globalAlpha = 0.9;
    ctx.fillText('W', 0, R * 0.01);
    ctx.globalAlpha = 1;

    // Laurel left
    drawLaurel(ctx, R, -1, metal);
    drawLaurel(ctx, R, 1, metal);

    // Top banner arc text
    ctx.save();
    ctx.font = (R * 0.078) + 'px Times New Roman, Georgia, serif';
    ctx.fillStyle = frost;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    var label = 'WASTED TOKEN MINT';
    var arcR = R * 0.62;
    for (var ci = 0; ci < label.length; ci++) {
      var u = (ci / (label.length - 1)) - 0.5;
      var ang = u * 1.55;
      var ch = label[ci];
      ctx.save();
      ctx.rotate(ang);
      ctx.translate(0, -arcR);
      // emboss: dark then light offset
      ctx.fillStyle = metal.dark;
      ctx.fillText(ch, 0.8, 0.8);
      ctx.fillStyle = frost;
      ctx.fillText(ch, 0, 0);
      ctx.restore();
    }
    ctx.restore();

    // Bottom arc
    ctx.save();
    ctx.font = (R * 0.07) + 'px Times New Roman, Georgia, serif';
    var label2 = 'CHALLENGE COIN';
    var arcR2 = R * 0.62;
    for (var cj = 0; cj < label2.length; cj++) {
      var u2 = (cj / (label2.length - 1)) - 0.5;
      var ang2 = Math.PI - u2 * 1.35;
      ctx.save();
      ctx.rotate(ang2);
      ctx.translate(0, -arcR2);
      ctx.rotate(Math.PI);
      ctx.fillStyle = metal.dark;
      ctx.textAlign = 'center';
      ctx.fillText(label2[cj], 0.8, 0.8);
      ctx.fillStyle = frost;
      ctx.fillText(label2[cj], 0, 0);
      ctx.restore();
    }
    ctx.restore();

    // Stars
    drawStar(ctx, -R * 0.72, 0, R * 0.04, metal);
    drawStar(ctx, R * 0.72, 0, R * 0.04, metal);
  }

  function drawLaurel(ctx, R, side, metal) {
    ctx.save();
    ctx.strokeStyle = metal.frost;
    ctx.fillStyle = metal.mid;
    ctx.lineWidth = R * 0.012;
    for (var i = 0; i < 7; i++) {
      var yy = R * 0.28 - i * R * 0.09;
      var xx = side * (R * 0.38 + Math.sin(i * 0.7) * R * 0.02);
      ctx.save();
      ctx.translate(xx, yy);
      ctx.rotate(side * (0.6 - i * 0.12));
      ctx.beginPath();
      ctx.ellipse(0, 0, R * 0.07, R * 0.028, 0, 0, Math.PI * 2);
      // relief
      var lg = ctx.createLinearGradient(-R * 0.05, 0, R * 0.05, 0);
      lg.addColorStop(0, metal.dark);
      lg.addColorStop(0.45, metal.frost);
      lg.addColorStop(1, metal.base);
      ctx.fillStyle = lg;
      ctx.fill();
      ctx.strokeStyle = metal.dark;
      ctx.lineWidth = R * 0.006;
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  function drawStar(ctx, x, y, s, metal) {
    ctx.save();
    ctx.translate(x, y);
    ctx.beginPath();
    for (var i = 0; i < 10; i++) {
      var a = -Math.PI / 2 + i * Math.PI / 5;
      var rad = i % 2 === 0 ? s : s * 0.4;
      var px = Math.cos(a) * rad;
      var py = Math.sin(a) * rad;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = metal.frost;
    ctx.fill();
    ctx.restore();
  }

  function drawBackDenomination(ctx, R, metal, light) {
    var frost = metal.frost;

    // Concentric guides
    ctx.beginPath();
    ctx.arc(0, 0, R * 0.78, 0, Math.PI * 2);
    ctx.strokeStyle = metal.rim;
    ctx.lineWidth = R * 0.02;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, R * 0.7, 0, Math.PI * 2);
    ctx.strokeStyle = mixHex(metal.dark, metal.hi, 0.4);
    ctx.lineWidth = R * 0.008;
    ctx.stroke();

    // Field hatch (subtle machine lines)
    ctx.save();
    ctx.globalAlpha = 0.12;
    ctx.strokeStyle = metal.dark;
    ctx.lineWidth = 1;
    for (var h = -R; h < R; h += R * 0.06) {
      ctx.beginPath();
      ctx.moveTo(-R, h);
      ctx.lineTo(R, h);
      ctx.stroke();
    }
    ctx.restore();

    // "DENOMINATION" header
    ctx.font = (R * 0.065) + 'px Times New Roman, Georgia, serif';
    ctx.fillStyle = frost;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = metal.dark;
    ctx.fillText('DENOMINATION', 0.7, -R * 0.38 + 0.7);
    ctx.fillStyle = frost;
    ctx.fillText('DENOMINATION', 0, -R * 0.38);

    // Big number
    var amount = '10,000';
    ctx.font = 'bold ' + (R * 0.28) + 'px Times New Roman, Georgia, serif';
    // emboss
    ctx.fillStyle = metal.dark;
    ctx.fillText(amount, 1.5, 1.5);
    var tg = ctx.createLinearGradient(0, -R * 0.2, 0, R * 0.2);
    tg.addColorStop(0, frost);
    tg.addColorStop(0.5, metal.hi);
    tg.addColorStop(1, metal.base);
    ctx.fillStyle = tg;
    ctx.fillText(amount, 0, 0);

    // TOKENS
    ctx.font = (R * 0.12) + 'px Times New Roman, Georgia, serif';
    ctx.fillStyle = metal.dark;
    ctx.fillText('TOKENS', 1, R * 0.28 + 1);
    ctx.fillStyle = frost;
    ctx.fillText('TOKENS', 0, R * 0.28);

    // Small serial ring text
    ctx.font = (R * 0.055) + 'px Times New Roman, Georgia, serif';
    ctx.fillStyle = metal.mid;
    ctx.fillText('PROOF · STRUCK AT WTM', 0, R * 0.52);

    // Center micro emblem
    ctx.beginPath();
    ctx.arc(0, -R * 0.55, R * 0.05, 0, Math.PI * 2);
    ctx.fillStyle = metal.dark;
    ctx.fill();
    ctx.strokeStyle = frost;
    ctx.lineWidth = R * 0.01;
    ctx.stroke();
  }

  function drawSpecular(ctx, fx, fy, ellX, ellY, light, metal, facing, t) {
    ctx.save();
    ellipsePath(ctx, fx, fy, ellX * 0.98, ellY * 0.98);
    ctx.clip();

    // Primary specular blob — moves with light / time
    var sx = fx + light.x * ellX * 0.62;
    var sy = fy + light.y * ellY * 0.55 - ellY * 0.1;
    var sr = Math.max(ellX, ellY) * 0.55;
    var sg = ctx.createRadialGradient(sx, sy, 0, sx, sy, sr);
    var intensity = 0.25 + 0.35 * Math.abs(facing);
    sg.addColorStop(0, 'rgba(255,255,255,' + (0.55 * intensity + 0.15) + ')');
    sg.addColorStop(0.2, 'rgba(255,250,230,' + (0.25 * intensity) + ')');
    sg.addColorStop(0.5, 'rgba(255,240,200,0.06)');
    sg.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sg;
    ctx.fillRect(fx - ellX * 2, fy - ellY * 2, ellX * 4, ellY * 4);

    // Secondary long specular streak (rake)
    var ang = Math.atan2(light.y, light.x) + 0.15;
    ctx.save();
    ctx.translate(fx + light.x * ellX * 0.2, fy + light.y * ellY * 0.15);
    ctx.rotate(ang);
    var streak = ctx.createLinearGradient(0, -ellY, 0, ellY);
    streak.addColorStop(0, 'rgba(255,255,255,0)');
    streak.addColorStop(0.4, 'rgba(255,255,255,0)');
    streak.addColorStop(0.5, 'rgba(255,255,255,' + (0.22 + 0.2 * Math.abs(Math.sin(t * Math.PI * 2))) + ')');
    streak.addColorStop(0.6, 'rgba(255,255,255,0)');
    streak.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = streak;
    ctx.fillRect(-ellX * 1.1, -ellY * 1.1, ellX * 2.2, ellY * 2.2);
    // thin hot line
    var hot = ctx.createLinearGradient(-ellX, 0, ellX, 0);
    hot.addColorStop(0, 'rgba(255,255,255,0)');
    hot.addColorStop(0.45, 'rgba(255,255,255,0)');
    hot.addColorStop(0.5, 'rgba(255,255,255,' + (0.4 * intensity) + ')');
    hot.addColorStop(0.55, 'rgba(255,255,255,0)');
    hot.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = hot;
    ctx.fillRect(-ellX, -ellY * 0.08, ellX * 2, ellY * 0.16);
    ctx.restore();

    ctx.restore();
  }

  function drawRim(ctx, fx, fy, ellX, ellY, metal, light, facing) {
    ctx.save();
    ellipsePath(ctx, fx, fy, ellX, ellY);
    ctx.strokeStyle = 'rgba(255,255,255,' + (0.08 + 0.12 * Math.abs(facing)) + ')';
    ctx.lineWidth = 2;
    ctx.stroke();
    // bright arc where light hits rim
    ctx.beginPath();
    var a0 = Math.atan2(light.y, light.x) - 0.9;
    var a1 = a0 + 1.8;
    ctx.ellipse(fx, fy, ellX, ellY, 0, a0, a1);
    ctx.strokeStyle = 'rgba(255,255,255,0.35)';
    ctx.lineWidth = Math.max(2, ellX * 0.03);
    ctx.stroke();
    ctx.restore();
  }

  // ---------- Hero setup ----------
  var heroCanvas = document.getElementById('coin-hero');
